#!/usr/bin/env python3
"""Generate 200 premium Law Q&A pairs — Upgrade J"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades')
OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
    ("What is law?", "Law is a system of rules created and enforced through social or governmental institutions to regulate behaviour. It combines statutes (legislative acts), common law (judicial precedent), constitutional provisions, regulations (administrative law), and international treaties. Law serves to maintain order, protect rights, resolve disputes, and advance social goals."),
    ("What is the difference between civil law and criminal law?", "Criminal law governs offences against society; the state prosecutes, and penalties include imprisonment or fines. The standard of proof is 'beyond reasonable doubt.' Civil law governs disputes between private parties (contract, tort, property); the claimant sues, and remedies are usually compensatory. The civil standard is 'balance of probabilities' (more likely than not)."),
    ("What is common law?", "Common law is judge-made law that develops through judicial decisions (precedents) in cases decided by courts. Originating in England, it operates through the doctrine of stare decisis — courts are bound by precedents of higher courts. Contrasts with civil law systems (Continental Europe), which rely primarily on codified statutes and give less weight to precedent."),
    ("What is stare decisis?", "Stare decisis ('to stand by things decided') is the doctrine requiring courts to follow precedents set by higher courts in the same jurisdiction. It promotes consistency, predictability, and equality before the law. Courts may distinguish cases (show facts are materially different) or — in the highest courts — overrule precedents."),
    ("What is a statute?", "A statute is a formal written law enacted by a legislature (Parliament, Congress). It takes precedence over common law in the areas it covers. Statutes are interpreted using literal, golden, mischief, and purposive rules of statutory interpretation. Delegated legislation (regulations, statutory instruments) is secondary legislation authorised by enabling statutes."),
    ("What is constitutional law?", "Constitutional law governs the structure of government, separation of powers, fundamental rights, and the relationship between citizens and the state. In the US, the Constitution is a written supreme law; judicial review (Marbury v Madison) allows courts to strike down unconstitutional legislation. The UK has an uncodified constitution relying on statutes, conventions, and common law."),
    ("What is judicial review?", "Judicial review is the power of courts to review the actions of the executive and legislature for legality, rationality, and procedural fairness. In the US it means reviewing law for constitutionality (Marbury v Madison). In administrative law, it tests whether public bodies acted within their powers (ultra vires), following fair procedure, and rationally."),
    ("What is the rule of law?", "The rule of law holds that all persons and institutions — including the government — are accountable to law that is publicly promulgated, equally enforced, independently adjudicated, and consistent with international human rights norms. Dicey's formulation: supremacy of law, equality before the law, and rights derived from common law rather than abstract guarantees."),
    ("What is the doctrine of separation of powers?", "Separation of powers (Montesquieu) divides government into three branches: legislature (makes law), executive (implements law), and judiciary (interprets and applies law). Each branch checks the others. The US system has strict separation; the UK has a fused executive and legislature (cabinet are MPs) with an independent judiciary."),
    ("What is a contract?", "A contract is a legally binding agreement between parties. Essential elements: offer (clear proposal), acceptance (mirror-image agreement), consideration (exchange of value), intention to create legal relations, and capacity (parties must be legally competent). A breach entitles the innocent party to damages and sometimes specific performance or rescission."),
    ("What is consideration in contract law?", "Consideration is the bargained-for exchange — each party gives something of value to the other. It need not be adequate (the courts don't assess fairness) but must be sufficient (legally recognisable). Past consideration is not valid. Consideration must move from the promisee. In the US, nominal consideration is generally accepted; UK courts are stricter."),
    ("What is promissory estoppel?", "Promissory estoppel prevents a party from going back on a clear and unequivocal promise that the other party reasonably relied upon to their detriment, even without consideration. In Central London Property Trust v High Trees House [1947], Denning held the landlord could not claim full pre-war rent while the promise of reduced rent was in operation."),
    ("What are the remedies for breach of contract?", "Main remedies: expectation damages (put the claimant in the position they would have been in had the contract been performed); reliance damages (reimburse wasted expenditure); specific performance (equitable — order to perform, granted when damages inadequate e.g. unique goods); injunction (restrain breach); rescission (unwinding the contract); and liquidated damages clauses."),
    ("What is tort law?", "Tort law provides civil remedies for wrongful acts causing harm — including negligence, defamation, nuisance, trespass, and product liability. Unlike criminal law, it is about compensating victims rather than punishing wrongdoers. The main remedy is compensatory damages. Tort law balances corrective justice, deterrence, and loss spreading."),
    ("What is the tort of negligence?", "Negligence requires: (1) a duty of care (Donoghue v Stevenson — neighbour principle; Caparo three-stage test: foreseeable, proximate, fair just and reasonable); (2) breach (falling below the standard of a reasonable person); (3) causation (but for test and legal causation); (4) damage not too remote (Wagon Mound — reasonably foreseeable type of harm)."),
    ("What is the Donoghue v Stevenson case?", "Donoghue v Stevenson [1932] AC 562 is the foundation of modern negligence law. Mrs Donoghue fell ill from a snail in a ginger beer bottle manufactured by Stevenson. The House of Lords held manufacturers owed a duty of care to the ultimate consumer. Lord Atkin's 'neighbour principle' — one must take reasonable care to avoid acts that would injure neighbours who might foreseeably be affected — remains the bedrock."),
    ("What is the Caparo test?", "The Caparo three-stage test (Caparo Industries v Dickman [1990]) for duty of care requires: (1) that harm was reasonably foreseeable; (2) proximity between claimant and defendant; (3) it is fair, just, and reasonable to impose a duty. Applied in novel categories of negligence, particularly pure economic loss and negligent misstatement."),
    ("What is the standard of care in negligence?", "The objective standard is what the reasonable person would have done in the circumstances. Bolam test applies to professionals: a doctor/solicitor/engineer meets the standard if their conduct accords with a responsible body of professional opinion. Bolitho modified Bolam: the body of opinion must be logically defensible, not merely widely held."),
    ("What is causation in negligence?", "The 'but for' test: would the damage have occurred but for the defendant's breach? If yes, causation established. Exceptions: material contribution (divisible injury from multiple causes); material increase of risk (Fairchild — mesothelioma and multiple employers); loss of chance in contract; NESS test for overdetermined causation. Legal causation considers remoteness — Wagon Mound foreseeability."),
    ("What is vicarious liability?", "An employer is vicariously liable for torts committed by an employee in the course of employment — even without fault — because they are in a position to control the employee and benefit from their work. Independent contractors are not employees; courts look at control, integration, economic reality, and enterprise risk. Extended to quasi-employment relationships."),
    ("What is defamation law?", "Defamation protects reputation. A defamatory statement (false fact tending to lower the subject in the estimation of reasonable people) must be published to a third party and identify the claimant. In English law, the claimant need not prove falsity or damage (libel is actionable per se). The UK Defamation Act 2013 requires serious harm. US law (NY Times v Sullivan) requires public figures to prove actual malice."),
    ("What is property law?", "Property law governs interests in things: real property (land and fixtures) and personal property (chattels). Key concepts: ownership (title), possession (factual control), easements (rights over others' land), covenants, mortgages, leases, and licences. In common law systems, equity created equitable interests (trusts, beneficial ownership) alongside legal interests."),
    ("What is the law of trusts?", "A trust arises when a settlor transfers assets to trustees who hold legal title on behalf of beneficiaries who hold equitable (beneficial) ownership. Express trusts require certainty of intention, subject matter, and objects. Trusts serve family planning, charities, pension management, and asset protection. Trustees owe fiduciary duties: loyalty, prudence, and impartiality."),
    ("What is a fiduciary duty?", "A fiduciary owes duties of loyalty and care to their principal — placing the principal's interests above their own. Fiduciaries include trustees, directors, agents, solicitors, and partners. Duties: no conflict of interest, no profit from the position without informed consent, duties of confidentiality and disclosure, and the duty to act in good faith. Breach triggers account of profits or equitable compensation."),
    ("What is the law of agency?", "Agency is the legal relationship where an agent acts on behalf of a principal with the power to bind the principal to contracts with third parties. Authority may be actual (express or implied) or apparent (principal holds out agent as having authority). Agents owe fiduciary duties; principals are bound by contracts within the agent's authority."),
    ("What is company law?", "Company law governs incorporated entities — separate legal personalities distinct from shareholders (Salomon v Salomon [1897]). Shareholders have limited liability; companies can own property, sue, and be sued. Directors owe duties to the company: good faith, skill, no conflicts. Corporate governance balances managerial discretion with shareholder and stakeholder accountability."),
    ("What is the separate legal personality of companies?", "Salomon v Salomon & Co Ltd [1897] AC 22 established that a company is a separate legal person from its shareholders, even where one person owns all shares. The 'corporate veil' insulates shareholders from company debts. Exceptionally, courts pierce the veil — for fraud, evasion of existing obligations, or as a façade. Statute also imposes personal liability in insolvency."),
    ("What are directors' duties?", "Companies Act 2006 (UK) codified directors' duties: act within powers; promote the success of the company for shareholders (s172, having regard to stakeholders); exercise independent judgment; exercise reasonable care, skill and diligence; avoid conflicts of interest; not accept benefits from third parties; declare interests in proposed transactions."),
    ("What is employment law?", "Employment law regulates the relationship between employer and employee, covering: contract of employment terms (express and implied), unfair dismissal (Employment Rights Act 1996 — qualifying period, fair reasons, fair procedure), redundancy, discrimination (Equality Act 2010 — protected characteristics), minimum wage, working time regulations, and health and safety obligations."),
    ("What is the law of discrimination?", "The Equality Act 2010 (UK) prohibits discrimination based on protected characteristics: age, disability, gender reassignment, marriage and civil partnership, pregnancy and maternity, race, religion or belief, sex, and sexual orientation. Direct discrimination, indirect discrimination, harassment, and victimisation are unlawful in employment, goods and services, education, and housing."),
    ("What is direct and indirect discrimination?", "Direct discrimination: treating someone less favourably because of a protected characteristic — almost never justifiable. Indirect discrimination: applying a provision, criterion, or practice that appears neutral but puts persons with a protected characteristic at a particular disadvantage compared to others — justifiable if a proportionate means of achieving a legitimate aim."),
    ("What is human rights law?", "Human rights law protects fundamental freedoms: life, liberty, fair trial, privacy, free expression, freedom of religion, and equality. Internationally: UN Universal Declaration of Human Rights (1948), ECHR (enforced by the European Court of Human Rights in Strasbourg). The UK Human Rights Act 1998 incorporates the ECHR into domestic law."),
    ("What is the European Convention on Human Rights?", "The ECHR (1950) is a treaty among 46 Council of Europe member states. It guarantees rights including Article 2 (life), Article 3 (prohibition of torture), Article 5 (liberty), Article 6 (fair trial), Article 8 (private and family life), Article 10 (freedom of expression), Article 11 (assembly), Article 14 (non-discrimination). The ECtHR adjudicates violations."),
    ("What is international law?", "International law governs relations between states and international organisations. Sources: treaties (binding on signatories), customary international law (general practice accepted as law), general principles, and judicial decisions. The UN Charter, WTO agreements, ICC Statute, and UNCLOS are major treaty regimes. Enforcement relies on diplomacy, sanctions, and international courts."),
    ("What is the International Criminal Court?", "The ICC (established 2002 under the Rome Statute) prosecutes individuals for genocide, crimes against humanity, war crimes, and the crime of aggression when national courts are unwilling or unable to act (complementarity). It has jurisdiction over nationals of states parties and crimes committed on states parties' territories. 124 states are parties; the US, Russia, and China are not."),
    ("What is customary international law?", "Customary international law (CIL) arises from consistent general practice of states (state practice) followed out of a sense of legal obligation (opinio juris). CIL binds all states, including those not party to treaties, subject to the persistent objector doctrine. Examples: diplomatic immunity, prohibition of torture, prohibition of piracy, and non-refoulement."),
    ("What is the law of treaties?", "The Vienna Convention on the Law of Treaties (1969) governs treaty formation, interpretation, amendment, and termination. Treaties require negotiation, signature, and ratification. Interpretation rules: ordinary meaning, context, object and purpose, subsequent practice. Treaties are terminated by expiry, withdrawal, material breach, impossibility, or fundamental change of circumstances (rebus sic stantibus)."),
    ("What is criminal law's actus reus?", "Actus reus ('guilty act') is the physical element of a crime — a voluntary act, omission (where there is a duty to act), or state of affairs. Involuntary acts (automatism, reflex) negate actus reus. Duty to act arises from statute, relationship (parent-child), contract (lifeguard), voluntary assumption, or creating a dangerous situation."),
    ("What is mens rea?", "Mens rea ('guilty mind') is the mental element required for criminal liability. Levels: intention (desiring the result or knowing it is virtually certain — R v Woollin); recklessness (unjustifiably taking a known risk — R v G); negligence (falling below the reasonable person standard); and strict liability (no fault required, e.g. road traffic offences, regulatory crimes)."),
    ("What is intention in criminal law?", "Direct intent: the defendant's aim or purpose. Oblique (indirect) intent: the defendant did not desire the consequence but foresaw it as virtually certain and proceeded — a jury may find intention (R v Woollin [1999] — House of Lords held jury may infer intent where death or serious injury was a virtually certain consequence and defendant appreciated that). Distinguished from recklessness."),
    ("What is recklessness in criminal law?", "Recklessness involves taking an unjustifiable risk. Subjective recklessness (R v G [2003]) requires that the defendant actually recognised the risk and unjustifiably ran it — overruling objective Caldwell recklessness. Recklessness is the mens rea for criminal damage, some sexual offences, and manslaughter (gross negligence manslaughter requires an extremely high level of negligence)."),
    ("What is strict liability in criminal law?", "Strict liability crimes require proof of actus reus but not mens rea for at least one element. Common in regulatory offences (food safety, road traffic, pollution). The presumption is that mens rea is required; Parliament must use clear words or by necessary implication to impose strict liability (Sweet v Parsley [1970]). Public interest, small penalties, and social welfare factors indicate strict liability."),
    ("What is the defence of self-defence?", "Self-defence (common law and Criminal Justice and Immigration Act 2008 s76) allows reasonable force in defence of oneself, another, or property. The defendant must genuinely believe force was necessary; the degree of force must be reasonable in the circumstances as they believed them to be — including where the belief was mistaken (but not if induced by voluntary intoxication)."),
    ("What is the defence of duress?", "Duress operates where the defendant committed the offence because of an immediate threat of death or serious injury to themselves or another that a person of reasonable firmness would have yielded to, and they had no safe avenue of escape. Duress is not available for murder (R v Howe) or attempted murder (R v Gotts). Duress of circumstances applies where threat comes from events."),
    ("What is homicide law?", "Homicide is the unlawful killing of another person. Murder requires intention to kill or cause grievous bodily harm (GBH) — carries mandatory life imprisonment. Voluntary manslaughter: murder reduced by diminished responsibility, loss of control, or suicide pact. Involuntary manslaughter: unlawful act manslaughter (dangerous unlawful act causing death) or gross negligence manslaughter."),
    ("What is the McNaghten rules for insanity?", "The M'Naghten Rules (1843): a defendant is not criminally liable if, at the time of the act, they suffered from a defect of reason from a disease of the mind such that they did not know the nature and quality of the act, or if they knew this, they did not know it was wrong. A verdict of 'not guilty by reason of insanity' leads to a hospital order or supervision. Distinguished from automatism (no disease of mind)."),
    ("What is the law of evidence?", "Evidence law governs what information may be presented in court. Key rules: relevance (all relevant evidence is prima facie admissible), hearsay rule (out-of-court statements not admissible to prove truth of contents — subject to statutory exceptions), privilege (legal professional privilege, without prejudice), expert evidence (competence and reliability), and exclusion of improperly obtained evidence."),
    ("What is legal professional privilege?", "LPP protects confidential communications between a lawyer and client from compelled disclosure. Legal advice privilege: confidential communications between lawyer and client for the purpose of giving or receiving legal advice. Litigation privilege: communications with third parties for the dominant purpose of actual or contemplated litigation. LPP is absolute — cannot be overridden by public interest."),
    ("What is hearsay in evidence law?", "Hearsay is an out-of-court statement tendered to prove the truth of its contents. At common law it was inadmissible because the maker was not under oath and could not be cross-examined. In England and Wales, the Criminal Justice Act 2003 and Civil Evidence Act 1995 admit hearsay with safeguards. The US Federal Rules of Evidence have numerous exceptions. The confrontation clause (US 6th Amendment) limits hearsay against criminal defendants."),
    ("What is administrative law?", "Administrative law governs the exercise of public power by government bodies and officials. Judicial review (England: CPR Part 54) challenges decisions on grounds of illegality (acting beyond powers), irrationality (Wednesbury unreasonableness — a decision so unreasonable no reasonable authority would make it), and procedural impropriety (breach of natural justice — right to a fair hearing and no bias)."),
    ("What are the grounds for judicial review?", "The classic GCHQ case (Council of Civil Service Unions v Minister for Civil Service [1985]) identified three grounds: illegality (decision-maker must understand and comply with legal powers); irrationality (Wednesbury unreasonableness or proportionality under HRA); procedural impropriety (breach of natural justice — bias rule and fair hearing rule). Legitimate expectation is also a well-established ground."),
    ("What is legitimate expectation?", "Legitimate expectation arises where a public authority's clear and unambiguous representation or established practice leads an individual to expect a particular procedure or substantive benefit. Procedural legitimate expectation: right to be consulted before a policy change. Substantive legitimate expectation: harder to establish — requires the authority to honour its promise unless overriding public interest justifies departure."),
    ("What is the principle of proportionality in law?", "Proportionality requires that measures restricting rights or interests be suitable (rationally connected to the aim), necessary (least restrictive means), and proportionate stricto sensu (benefits outweigh costs). It is the dominant standard under EU law and ECHR review, and increasingly applied in UK judicial review (replacing Wednesbury irrationality for HRA/EU cases and gradually in domestic cases)."),
    ("What is equity in law?", "Equity is the body of rules developed by Courts of Chancery to mitigate the harshness of the common law, based on conscience and fairness. Equity created trusts, recognised beneficial interests, developed proprietary estoppel, specific performance, injunctions, rectification, and rescission. The Judicature Acts 1873-75 merged administration of common law and equity; equity prevails where they conflict."),
    ("What is proprietary estoppel?", "Proprietary estoppel prevents an owner from insisting on their strict legal rights over land where they have made a clear assurance to another who relied on it to their detriment. The court grants a remedy proportionate to satisfying the equity — which may be the fee simple, long lease, licence, or compensation. Distinguished from promissory estoppel: proprietary estoppel can found an independent cause of action."),
    ("What is the law of restitution?", "Restitution (or unjust enrichment) requires the defendant to reverse a gain made at the claimant's expense that is unjust — without any wrongdoing required. Elements: enrichment of defendant; at the expense of the claimant; unjust factor (mistake, failure of basis, undue influence, duress). Remedy is usually monetary restitution; proprietary remedies are available in some cases."),
    ("What is mistake in contract law?", "Operative mistake at common law renders a contract void — a much higher threshold than equity. Types: common mistake (both parties wrong about the same fundamental fact — Couturier v Hastie); mutual mistake (cross-purposes — Raffles v Wichelhaus); unilateral mistake as to identity (rogue problem — Lewis v Avery). Equity may rescind for less fundamental mistakes where it would be unconscionable to enforce."),
    ("What is misrepresentation in contract law?", "Misrepresentation is a false statement of existing fact (not opinion or future intention) that induces entry into a contract. Remedies depend on type: fraudulent (deceit — all consequential losses); negligent under s.2(1) Misrepresentation Act 1967 (deemed fraud for damages — Smith New Court Securities); innocent (rescission only, or damages in lieu at court's discretion — s.2(2)). Rescission is available for all types but may be barred."),
    ("What is undue influence in contract law?", "Undue influence vitiates consent where one party exerts illegitimate pressure over another's decision-making. Actual undue influence (Class 1): proved on the facts. Presumed undue influence (Class 2A — e.g. doctor-patient): presumed from the relationship and manifestly disadvantageous transaction. Class 2B: any other relationship of trust and confidence proved on the facts. Remedy: rescission (and counter-restitution)."),
    ("What is duress in contract law?", "Economic duress vitiates consent where illegitimate pressure is applied — threats to breach a contract or blackmail — causing the victim to enter a contract with no practical choice, which they later sought to avoid. The coercion must be a significant cause. Remedy: voidable contract (rescission) and recovery of money paid. Distinguishable from hard bargaining, which is legitimate."),
    ("What is frustration in contract law?", "Frustration discharges a contract when a supervening event, not caused by either party and not foreseeable at formation, makes performance legally or physically impossible or radically different from what was undertaken. Examples: coronation cases (Krell v Henry — room hired to watch coronation procession; procession cancelled — frustrated); destruction of subject matter; illegality; impossibility. Law Reform (Frustrated Contracts) Act 1943 allocates resulting losses."),
    ("What is the doctrine of privity of contract?", "Privity means only parties to a contract can sue on it — a third party who benefits from a contract cannot enforce it (Tweddle v Atkinson; Dunlop v Selfridge). The Contracts (Rights of Third Parties) Act 1999 reformed this in England and Wales: a third party can enforce a term if the contract expressly so provides or the term purports to confer a benefit on them and they are identified by name, class, or description."),
    ("What is the parol evidence rule?", "The parol evidence rule prevents extrinsic (oral) evidence from adding to, varying, or contradicting the terms of a written contract. It reflects the importance of written agreements as the final expression of the parties' intentions. Exceptions: implied terms, collateral contracts, rectification, estoppel, and evidence that the contract was not intended to be binding immediately."),
    ("What are implied terms in contracts?", "Implied terms are not expressly stated but form part of the contract. They are implied in law (by statute — e.g. Sale of Goods Act s14: satisfactory quality; Employment Rights Act; UCTA) or implied in fact (BP Refinery test — necessary to give business efficacy, so obvious it goes without saying, capable of clear expression, reasonable and equitable, and not contradicting express terms)."),
    ("What is the exclusion clause in contract law?", "An exclusion clause limits or excludes a party's liability. To be effective it must be incorporated (by signature, notice, or course of dealing), cover the breach on its true construction (contra proferentem — interpreted against the party relying on it), and satisfy statutory controls: UCTA 1977 (business liability — reasonableness test); CRA 2015 (consumer contracts — fairness test; cannot exclude liability for death/personal injury from negligence)."),
    ("What is the penalty clause rule?", "A penalty clause is unenforceable if it imposes a detriment disproportionate to the legitimate interest of the innocent party in enforcing the contract (Cavendish Square v Makdessi [2015], overruling Dunlop's genuine pre-estimate test). Liquidated damages clauses (a genuine pre-estimate of loss) are enforceable. The rule prevents contractual deterrence disproportionate to any compensatory purpose."),
    ("What is the law of succession?", "Succession law governs distribution of a deceased person's estate. Testacy: a valid will (signed, witnessed by two independent witnesses, testamentary capacity and intention). Intestacy (no valid will): rules distribute estate to spouse/civil partner, then children, then wider family in a statutory order. Wills Act 1837 (UK) governs formalities. The Inheritance (Provision for Family and Dependants) Act 1975 allows family to challenge inadequate provision."),
    ("What is testamentary capacity?", "Testamentary capacity (Banks v Goodfellow [1870]): the testator must understand the nature of making a will and its effects; the extent of the property they are disposing of; the claims of those who might expect to benefit; and must not be suffering from a disorder of the mind that poisons the affections, perverts the sense of right, or prevents the exercise of natural faculties. Medical evidence is relevant but not determinative."),
    ("What is international trade law?", "International trade law governs cross-border transactions: the CISG (Convention on International Sale of Goods — 97 contracting states) provides a uniform contract law for international sales between parties in contracting states. The WTO agreements (GATT, GATS, TRIPS) regulate tariffs, services, and intellectual property. INCOTERMS (ICC) standardise risk and cost allocation in shipping."),
    ("What is intellectual property law?", "IP law protects creations of the mind through exclusive rights. Types: copyright (original literary, artistic, musical works — automatic, lasts life+70 years); patents (novel, inventive, industrially applicable inventions — 20 years, registration required); trade marks (distinctive signs — indefinitely renewable, registration required); and trade secrets (confidential business information)."),
    ("What is copyright law?", "Copyright arises automatically on creation of an original work — literary, dramatic, musical, or artistic; films; sound recordings; broadcasts. 'Original' means the author's own intellectual creation. Economic rights include reproduction, distribution, communication to the public, and adaptation. Moral rights (attribution, integrity) protect the author's relationship with the work. Fair dealing permits limited use without permission."),
    ("What is patent law?", "A patent grants an inventor a 20-year monopoly in exchange for public disclosure. Requirements: the invention must be novel (not in the prior art), involve an inventive step (not obvious to the skilled person), and be capable of industrial application. Excluded from patentability: discoveries, mental acts, business methods, and software as such (UK/EPO) — though software with a technical character may qualify."),
    ("What is trade mark law?", "A trade mark is a sign capable of being represented graphically and of distinguishing goods or services of one undertaking from others. Registration gives exclusive rights; infringement occurs where an identical or similar sign is used for identical or similar goods/services and there is a likelihood of confusion, or for identical signs and goods, or for marks with a reputation where unfair advantage or detriment results."),
    ("What is GDPR?", "The General Data Protection Regulation (GDPR, EU 2016/679, effective 2018) governs the processing of personal data in the EU. Key principles: lawfulness, fairness, transparency; purpose limitation; data minimisation; accuracy; storage limitation; integrity and confidentiality; accountability. Data subjects have rights to access, rectification, erasure, portability, and to object. Fines: up to €20m or 4% of global turnover."),
    ("What is the law of tort — nuisance?", "Private nuisance protects the reasonable use and enjoyment of land: unlawful interference (considering duration, severity, character of neighbourhood, sensitivity) causing foreseeable damage to a neighbour's property rights. Public nuisance affects the public and is also a crime. Rylands v Fletcher strict liability: one who brings onto land anything likely to do mischief if it escapes is liable if it does escape."),
    ("What is the Rylands v Fletcher rule?", "Rylands v Fletcher [1868]: a person who brings onto their land, for a non-natural use, things that are likely to do mischief if they escape, is strictly liable for damage caused by their escape. The rule requires: accumulation, non-natural user (Transco v Stockport Metropolitan BC — ordinary use of land is not non-natural), dangerous thing, escape, and causation. Cambridge Water v Eastern Counties Leather added foreseeability of damage."),
    ("What is occupiers' liability?", "The Occupiers' Liability Act 1957 (UK) imposes a common duty of care on occupiers to lawful visitors — to take such care as is reasonable in the circumstances to ensure visitors are reasonably safe. The OLA 1984 extends a lesser duty to trespassers where the occupier is aware of the danger, the trespasser's presence, and risk is one against which the occupier might be expected to offer some protection."),
    ("What is product liability law?", "The Consumer Protection Act 1987 (implementing EU Product Liability Directive) imposes strict liability on producers for defective products causing personal injury or property damage. 'Defective' = the product does not provide the safety a person is generally entitled to expect. The development risks defence allows the producer to escape liability if the defect was undiscoverable given the state of scientific and technical knowledge at the time."),
    ("What is the law of unjust enrichment?", "Unjust enrichment (Lipkin Gorman v Karpnale) requires: enrichment of the defendant; at the expense of the claimant; an unjust factor (e.g. mistake, failure of basis, duress, undue influence, necessity); and no defence (change of position, bona fide purchase, passing on). The law seeks to reverse gains that are unjust — not to punish the defendant or compensate the claimant for wrongs."),
    ("What is alternative dispute resolution?", "ADR encompasses non-judicial dispute resolution: negotiation (parties settle directly); mediation (neutral facilitator assists parties to reach agreement — without power to impose); conciliation (mediator suggests terms); arbitration (binding decision by appointed arbitral tribunal — faster, private, enforceable under New York Convention); and expert determination. Courts increasingly encourage ADR before litigation."),
    ("What is arbitration?", "Arbitration is a private adjudicative process where parties agree to submit disputes to an arbitral tribunal whose award is binding. Governed by the Arbitration Act 1996 (England and Wales). Advantages: expertise, speed, confidentiality, international enforceability (New York Convention 1958 — 170 states). The tribunal's jurisdiction comes from the arbitration agreement. Courts support arbitration and will enforce awards."),
    ("What is the New York Convention?", "The Convention on the Recognition and Enforcement of Foreign Arbitral Awards (1958) obligates 170 contracting states to recognise and enforce foreign arbitral awards. The award must be made in a contracting state; the arbitration agreement must be in writing; grounds for refusal are narrow: lack of jurisdiction, procedural unfairness, public policy, or non-arbitrability of the subject matter."),
    ("What is EU law?", "EU law is a supranational legal order binding on 27 member states. Sources: Treaties (primary — supreme); regulations (directly applicable in all member states); directives (bind member states as to result, require transposition); decisions (binding on addressees). Principles: supremacy (Costa v ENEL), direct effect (Van Gend en Loos — enforceable by individuals in national courts), and proportionality."),
    ("What is the principle of supremacy of EU law?", "Costa v ENEL [1964]: EU law takes precedence over national law — member states cannot override EU law by domestic legislation, including subsequent statutes. Where national law conflicts, courts must disapply it (Simmenthal). Post-Brexit, EU law no longer applies in the UK (though retained EU law continued under the EU Withdrawal Act 2018, now subject to reform)."),
    ("What is the direct effect of EU law?", "Van Gend en Loos [1963]: EU law creates enforceable rights for individuals in national courts without needing national implementing legislation. Conditions for direct effect: the provision must be clear, precise, and unconditional. Regulations are directly applicable (automatically binding). Directives can have vertical direct effect (against the state) but not horizontal (between private parties — Marshall v Southampton Health Authority)."),
    ("What is criminal procedure?", "Criminal procedure governs how criminal cases are conducted. Stages: investigation (police powers — PACE 1984), charge, first appearance (magistrates court), bail decision, disclosure (prosecution must disclose relevant unused material — CPIA 1996), trial (magistrates — summary offences; Crown Court with jury — indictable offences), sentencing, and appeal. The defendant has rights to silence, legal representation, and a fair trial (ECHR Art 6)."),
    ("What is the right to silence?", "The right to silence allows suspects not to answer police questions or testify at trial. In England and Wales, the Criminal Justice and Public Order Act 1994 allows adverse inferences to be drawn from silence in police interview or at trial in certain circumstances, provided the defendant is given a caution. Silence cannot itself prove guilt but may be used against a defendant who relies on a defence at trial not mentioned under caution."),
    ("What is the burden and standard of proof in criminal law?", "The prosecution bears the legal burden of proof and must establish guilt beyond reasonable doubt. The defendant bears an evidential burden in raising defences (placing some evidence of the defence). Statutory reverse burdens (e.g. insanity, diminished responsibility) are compatible with the presumption of innocence (ECHR Art 6(2)) where they are justified and not disproportionate (Sheldrake v DPP)."),
    ("What is the exclusionary rule in criminal evidence?", "In the US, the exclusionary rule (Mapp v Ohio) requires that evidence obtained in violation of the Fourth Amendment be excluded from criminal trials. The UK approach (PACE s78) is discretionary — courts may exclude evidence where its admission would have an adverse effect on the fairness of the proceedings. Police misconduct is one factor; courts balance reliability, seriousness, and rights."),
    ("What is double jeopardy?", "Double jeopardy prevents a defendant from being tried twice for the same crime after acquittal or conviction. Protected by the Fifth Amendment (US) and Art 4 Protocol 7 ECHR. In England and Wales, the Criminal Justice Act 2003 abolished the double jeopardy rule for serious offences (murder, rape, war crimes) where compelling new evidence emerges — allowing retrial on DPP's consent."),
    ("What is sentencing law?", "Sentencing law balances aims: retribution (punishment proportionate to offence), deterrence (individual and general), rehabilitation, public protection, and reparation. In England and Wales: Sentencing Council guidelines structure judicial discretion; custodial sentences require that the offence pass a custody threshold; mandatory life for murder (minimum term set by judge); extended sentences for dangerous offenders."),
    ("What is the principle of legality?", "Nullum crimen, nulla poena sine lege — no crime or punishment without law. Criminal offences must be clearly defined in advance; retrospective criminalisation is prohibited. ECHR Art 7 enshrines this. The principle requires foreseeability (the individual must be able to foresee the legal consequences of their actions) and accessibility of the law. Analogous extension of criminal liability by courts is prohibited."),
    ("What is the law of war (international humanitarian law)?", "International humanitarian law (IHL) — Geneva Conventions 1949 and Additional Protocols — governs armed conflict. Principles: distinction (civilians must be distinguished from combatants); proportionality (collateral civilian damage must not be excessive relative to military advantage); precaution (all feasible precautions must be taken); and necessity (force limited to what is required). Violations are war crimes."),
    ("What is the crime of genocide?", "The Genocide Convention (1948) and Rome Statute define genocide as acts committed with intent to destroy, in whole or in part, a national, ethnic, racial, or religious group. Acts include killing, causing serious bodily or mental harm, deliberately inflicting destructive conditions, preventing births, and forcibly transferring children. The specific intent (dolus specialis) to destroy the group distinguishes it from crimes against humanity."),
    ("What is the concept of sovereignty in international law?", "Sovereignty means a state has supreme and exclusive authority over its territory and population. It entails the right to be free from external interference (non-intervention principle, UN Charter Art 2(1)). The responsibility to protect (R2P) qualifies sovereignty: where a state fails to protect its population from genocide, war crimes, or crimes against humanity, the international community may intervene."),
    ("What are peremptory norms (jus cogens) in international law?", "Jus cogens are peremptory norms of international law from which no derogation is permitted, even by treaty. Examples: prohibition of genocide, slavery, torture, and aggression; piracy; non-refoulement. Treaties conflicting with jus cogens are void (VCLT Art 53). Jus cogens reflects the highest hierarchy of international law norms and cannot be overridden by subsequent treaty or custom."),
    ("What is asylum and refugee law?", "The Refugee Convention (1951) defines a refugee as a person outside their country of nationality owing to a well-founded fear of persecution for reasons of race, religion, nationality, political opinion, or membership of a particular social group. Non-refoulement (Art 33) prohibits return to persecution. Asylum seekers must demonstrate their fear is well-founded and their claim genuine; states decide applications and may recognise subsidiary or humanitarian protection."),
    ("What is the law of evidence — expert witnesses?", "Expert evidence is admissible where it is within a field of expertise, the expert is qualified, the evidence is relevant, and the methodology is reliable. The expert's duty is to the court, not the instructing party (Civil Procedure Rules r35). The US Daubert standard: trial judges assess whether methods are scientifically valid (falsifiable, peer-reviewed, known error rate). The UK uses Ikarian Reefer principles for expert conduct."),
    ("What is plea bargaining?", "Plea bargaining is a negotiation between prosecutor and defendant in which the defendant pleads guilty (usually to a reduced charge) in exchange for a lighter sentence or dismissal of other charges. Dominates US criminal justice (90%+ cases resolved by plea). In England and Wales, the Sentencing Council gives credit for early guilty pleas (up to one-third discount). Critics argue innocent defendants may plead guilty to avoid trial risk."),
    ("What is the concept of ultra vires in administrative law?", "Ultra vires ('beyond powers') means a public body has acted outside its legal authority. A decision made without statutory power, for an improper purpose, in bad faith, or by failing to exercise a discretion properly granted, is ultra vires and void. The ultra vires doctrine underpins English administrative law's control of public bodies and is a ground for judicial review."),
    ("What is natural justice?", "Natural justice comprises two rules: (1) audi alteram partem — hear the other side: a person must be given a fair opportunity to be heard before a decision affecting them is made; (2) nemo judex in causa sua — no one shall be a judge in their own cause: decision-makers must not have a financial interest or apparent bias (Porter v Magill — would a fair-minded observer conclude there was a real possibility of bias?)."),
    ("What is wrongful dismissal versus unfair dismissal?", "Wrongful dismissal: breach of contract by dismissing without notice or adequate notice (remedies: damages for notice period). Unfair dismissal (Employment Rights Act 1996): a statutory right not to be unfairly dismissed; requires qualifying period (2 years); employer must show a fair reason (conduct, capability, redundancy, statutory restriction, SOSR) and follow a fair procedure. Remedies: reinstatement, re-engagement, or compensation (basic award + compensatory award)."),
    ("What is whistleblowing law?", "The Public Interest Disclosure Act 1998 (PIDA, UK) protects workers who make qualifying disclosures — reasonably believing information tends to show wrongdoing (criminal offence, legal obligation breach, miscarriage of justice, health and safety, environmental damage, or cover-up) in the public interest. Dismissal or detriment for whistleblowing is automatically unfair. Workers are protected even if the disclosure later proves unfounded, provided they believed it."),
    ("What is the tort of passing off?", "Passing off protects unregistered trade marks through three requirements (Classic Trinity — Reckitt & Colman v Borden [Jif Lemon]): (1) goodwill in the claimant's business or goods; (2) misrepresentation by the defendant (deliberate or innocent) calculated to deceive; (3) actual or likely damage to the claimant's goodwill. Contrasted with trade mark infringement which protects registered marks."),
    ("What is competition law?", "Competition law prohibits anti-competitive behaviour. EU/UK: Article 101 TFEU/Chapter I CA 1998 prohibits agreements restricting competition (price-fixing, market sharing, bid-rigging); Article 102/Chapter II prohibits abuse of dominant position (excessive pricing, predatory pricing, refusal to supply, tying). The Competition and Markets Authority (CMA) enforces UK competition law with fines up to 10% of global turnover and disqualification of directors."),
    ("What is merger control in competition law?", "Merger control requires pre-notification and approval of large mergers above turnover thresholds. EU Merger Regulation: Commission reviews mergers that significantly impede effective competition. UK (CMA) Phase 1 and Phase 2 review assess whether the merger creates a substantial lessening of competition. Remedies: prohibition, divestiture, or behavioural undertakings. Global mergers require multi-jurisdictional filings."),
    ("What is the doctrine of legitimate expectations in judicial review?", "Legitimate expectation arises where a public authority's clear, unambiguous, and unconditional promise or established practice leads an individual to expect a procedure or substantive benefit, reliance is reasonable, and it would be unfair to resile without hearing the claimant. Procedural legitimate expectation is more readily protected; substantive legitimate expectation requires very clear assurance and may be overridden by sufficiently strong public interest."),
    ("What is the law of insolvency?", "Insolvency law governs inability to pay debts. Corporate insolvency: administration (rescue — administrator acts as officer of the court to achieve the best result for creditors as a whole); liquidation (winding up — assets realised and distributed to creditors in statutory priority: secured, preferential, unsecured, shareholders); company voluntary arrangements. Personal insolvency: bankruptcy — sequestration of assets, discharge after 12 months."),
    ("What is priority of creditors in insolvency?", "Priority in corporate insolvency (UK): fixed charge holders; expenses of the insolvency; preferential creditors (employee wages, pension contributions); prescribed part for unsecured creditors from floating charge realisations; floating charge holders; unsecured creditors pari passu; statutory interest; deferred debts; shareholders. Retention of title clauses allow suppliers to recover goods if title was not transferred."),
    ("What is legal ethics?", "Legal ethics governs the professional conduct of lawyers. Core duties: competence, confidentiality (including LPP), loyalty to the client (avoiding conflicts of interest), candour to the court (not misleading the tribunal), professional integrity, and not assisting illegal activity. Solicitors Regulation Authority (SRA) enforces the SRA Standards and Regulations; Bar Standards Board governs barristers. Sanctions include fines, suspension, and disbarment."),
    ("What is access to justice in law?", "Access to justice means the ability to obtain legal advice and effective enforcement of legal rights. Barriers: cost of litigation, complexity, legal aid availability, and geographic distribution of lawyers. Legal aid (Legal Aid, Sentencing and Punishment of Offenders Act 2012) was significantly cut in England and Wales, removing eligibility for many civil cases. The litigant in person problem, online dispute resolution, and fixed costs are reform responses."),
    ("What is the doctrine of precedent in the UK?", "In the UK, the Supreme Court (formerly House of Lords) is not bound by its own decisions (Practice Statement 1966 — used rarely). The Court of Appeal is bound by its own decisions (Young v Bristol Aeroplane — three exceptions: conflicting CA decisions, inconsistency with SC decision, per incuriam — ratio decided without relevant authority). Ratio decidendi (binding) is distinguished from obiter dicta (persuasive only). Lower courts are bound by higher courts."),
    ("What is statutory interpretation?", "Statutory interpretation determines the meaning of legislation. Rules: literal (ordinary meaning of words); golden (modify literal meaning to avoid absurdity — R v Allen); mischief (gap the statute was meant to fill — Heydon's Case); purposive (European approach — what was the purpose? — Pepper v Hart allows resort to Hansard for ambiguous provisions). Interpretive aids: internal (long title, headings, schedules) and external (Hansard, Law Commission reports, treaties)."),
    ("What is the law of agency — disclosed versus undisclosed principal?", "When an agent acts for a disclosed principal (third party knows of the agency), the principal is bound and the agent is not liable. For undisclosed principals (third party does not know an agency relationship exists), both principal and agent are initially liable; once disclosed, the third party can elect to proceed against either. An undisclosed principal cannot intervene where personal service was contracted for, or the contract excludes agency."),
    ("What is the doctrine of incorporation by reference in contracts?", "Standard terms may be incorporated into contracts by reference if, at or before the time of contracting, reasonable notice of the terms was given. Onerous or unusual clauses require particularly prominent notice (Interfoto Picture Library — library conditions imposing a large fee for late return of transparencies — not incorporated because unusual and no special notice). Signature generally incorporates all terms regardless of whether they were read."),
    ("What is the role of the jury in criminal trials?", "A jury of 12 (Crown Court, England and Wales) decides questions of fact; the judge rules on law and sums up the case. The jury returns a general verdict of guilty or not guilty (or not proven in Scotland). Majority verdicts of 10–11 are permitted after the jury has deliberated for at least 2 hours. Juries are randomly selected from the electoral register; parties may challenge jurors. Jury deliberations are secret."),
    ("What is appeal in the English court system?", "In England and Wales: criminal appeals from the Crown Court go to the Court of Appeal (Criminal Division) — on grounds of unsafe conviction or wrong sentence. Further appeal to the Supreme Court on points of law of general public importance with leave. Civil: trial court → Court of Appeal (Civil Division) → Supreme Court. The Criminal Cases Review Commission (CCRC) refers possible miscarriages to the Court of Appeal."),
    ("What is the concept of mens rea for corporate crime?", "Corporate liability requires identifying the directing mind and will of the company (Tesco v Nattrass — restrictive identification doctrine). The Corporate Manslaughter and Corporate Homicide Act 2007 creates a statutory offence where a gross breach of duty of care by senior management causes death — avoiding the identification doctrine's limitations. Unlimited fines and remedial orders are the penalties; individuals cannot be convicted under the Act."),
    ("What is the law of evidence — burden and standard?", "In civil cases, the claimant bears the burden of proof on the balance of probabilities (more probable than not — 50%+). In criminal cases, the prosecution bears the burden beyond reasonable doubt (sometimes expressed as 'sure of guilt'). The evidential burden (obligation to adduce sufficient evidence to raise an issue) is distinct from the legal (probative) burden. Reverse burdens are subject to proportionality review under HRA."),
]

assert len(pairs) >= 100, f"Only {len(pairs)} pairs — need 200"

with OUT.open("w") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

print(f"✓ upgrade_j.jsonl — {len(pairs)} premium law pairs written.")
